	publicAPI.setContainer = (el) => {
		if (model.el && model.el !== el) {
			if (model.canvas.parentNode !== model.el) RenderWindow_vtkErrorMacro("Error: canvas parent node does not match container");
			model.el.removeChild(model.canvas);
			if (model.el.contains(model.bgImage)) model.el.removeChild(model.bgImage);
		}
		if (model.el !== el) {
			model.el = el;
			if (model.el) {
				model.el.appendChild(model.canvas);
				if (model.useBackgroundImage) model.el.appendChild(model.bgImage);
			}
			publicAPI.modified();
		}
	};
	publicAPI.getContainer = () => model.el;
	publicAPI.getContainerSize = () => {
		if (!model.containerSize && model.el) {
			const { width, height } = model.el.getBoundingClientRect();
			model.containerSize = [width, height];
		}
		return model.containerSize || model.size;
	};
	publicAPI.getFramebufferSize = () => {
		return model.activeFramebuffer?.getSize() || model.size;
	};
	publicAPI.getPixelData = (x1, y1, x2, y2) => {
		const pixels = new Uint8Array((x2 - x1 + 1) * (y2 - y1 + 1) * 4);
		model.context.readPixels(x1, y1, x2 - x1 + 1, y2 - y1 + 1, model.context.RGBA, model.context.UNSIGNED_BYTE, pixels);
		return pixels;
	};
	publicAPI.get3DContext = (options = {
		preserveDrawingBuffer: false,
		depth: true,
		alpha: true,
		powerPreference: "high-performance"
	}) => {
		let result = null;
		const webgl2Supported = typeof WebGL2RenderingContext !== "undefined";
		model.webgl2 = false;
		if (model.defaultToWebgl2 && webgl2Supported) {
			result = model.canvas.getContext("webgl2", options);
			if (result) {
				model.webgl2 = true;
				RenderWindow_vtkDebugMacro("using webgl2");
			}
		}
		if (!result) {
			RenderWindow_vtkDebugMacro("using webgl1");
			result = model.canvas.getContext("webgl", options) || model.canvas.getContext("experimental-webgl", options);
		}
		if (!result) RenderWindow_vtkErrorMacro("no webgl context");
		return new Proxy(result, getCachingContextHandler());
	};
	publicAPI.get2DContext = (options = {}) => model.canvas.getContext("2d", options);
	publicAPI.restoreContext = () => {
		const rp = RenderPass/* ["default"].newInstance */.Ay.newInstance();
		rp.setCurrentOperation("Release");
		rp.traverse(publicAPI, null);
	};
	publicAPI.activateTexture = (texture) => {
		const result = model._textureResourceIds.get(texture);
		if (result !== void 0) {
			model.context.activeTexture(model.context.TEXTURE0 + result);
			return;
		}
		const activeUnit = publicAPI.getTextureUnitManager().allocate();
		if (activeUnit < 0) {
			RenderWindow_vtkErrorMacro("Hardware does not support the number of textures defined.");
			return;
		}
		model._textureResourceIds.set(texture, activeUnit);
		model.context.activeTexture(model.context.TEXTURE0 + activeUnit);
	};
	publicAPI.deactivateTexture = (texture) => {
		const result = model._textureResourceIds.get(texture);
		if (result !== void 0) {
			publicAPI.getTextureUnitManager().free(result);
			model._textureResourceIds.delete(texture);
		}
	};
	publicAPI.getTextureUnitForTexture = (texture) => {
		const result = model._textureResourceIds.get(texture);
		if (result !== void 0) return result;
		return -1;
	};
	publicAPI.getDefaultTextureByteSize = (vtkType, oglNorm16Ext = null, useHalfFloat = false) => {
		if (model.webgl2) switch (vtkType) {
			case Constants/* .VtkDataTypes.CHAR */.JA.CHAR:
			case Constants/* .VtkDataTypes.SIGNED_CHAR */.JA.SIGNED_CHAR:
			case Constants/* .VtkDataTypes.UNSIGNED_CHAR */.JA.UNSIGNED_CHAR: return 1;
			case oglNorm16Ext:
			case useHalfFloat:
			case Constants/* .VtkDataTypes.UNSIGNED_SHORT */.JA.UNSIGNED_SHORT:
			case Constants/* .VtkDataTypes.SHORT */.JA.SHORT:
			case Constants/* .VtkDataTypes.VOID */.JA.VOID: return 2;
			default: return 4;
		}
		return 1;
	};
	publicAPI.getDefaultTextureInternalFormat = (vtktype, numComps, oglNorm16Ext = null, useHalfFloat = false) => {
		if (model.webgl2) switch (vtktype) {
			case Constants/* .VtkDataTypes.UNSIGNED_CHAR */.JA.UNSIGNED_CHAR: switch (numComps) {
				case 1: return model.context.R8;
				case 2: return model.context.RG8;
				case 3: return model.context.RGB8;
				default: return model.context.RGBA8;
			}
			case oglNorm16Ext && !useHalfFloat && Constants/* .VtkDataTypes.UNSIGNED_SHORT */.JA.UNSIGNED_SHORT: switch (numComps) {
				case 1: return oglNorm16Ext.R16_EXT;
				case 2: return oglNorm16Ext.RG16_EXT;
				case 3: return oglNorm16Ext.RGB16_EXT;
				default: return oglNorm16Ext.RGBA16_EXT;
			}
			case oglNorm16Ext && !useHalfFloat && Constants/* .VtkDataTypes.SHORT */.JA.SHORT: switch (numComps) {
				case 1: return oglNorm16Ext.R16_SNORM_EXT;
				case 2: return oglNorm16Ext.RG16_SNORM_EXT;
				case 3: return oglNorm16Ext.RGB16_SNORM_EXT;
				default: return oglNorm16Ext.RGBA16_SNORM_EXT;
			}
			case Constants/* .VtkDataTypes.UNSIGNED_SHORT */.JA.UNSIGNED_SHORT:
			case Constants/* .VtkDataTypes.SHORT */.JA.SHORT:
			case Constants/* .VtkDataTypes.FLOAT */.JA.FLOAT:
			default: switch (numComps) {
				case 1: return useHalfFloat ? model.context.R16F : model.context.R32F;
				case 2: return useHalfFloat ? model.context.RG16F : model.context.RG32F;
				case 3: return useHalfFloat ? model.context.RGB16F : model.context.RGB32F;
				default: return useHalfFloat ? model.context.RGBA16F : model.context.RGBA32F;
			}
		}
		switch (numComps) {
			case 1: return model.context.LUMINANCE;
			case 2: return model.context.LUMINANCE_ALPHA;
			case 3: return model.context.RGB;
			default: return model.context.RGBA;
		}
	};
	publicAPI.setBackgroundImage = (img) => {
		model.bgImage.src = img.src;
	};
	publicAPI.setUseBackgroundImage = (value) => {
		model.useBackgroundImage = value;
		if (model.useBackgroundImage && !model.el.contains(model.bgImage)) model.el.appendChild(model.bgImage);
		else if (!model.useBackgroundImage && model.el.contains(model.bgImage)) model.el.removeChild(model.bgImage);
	};
	function getCanvasDataURL(format = model.imageFormat) {
		const temporaryCanvas = document.createElement("canvas");
		const temporaryContext = temporaryCanvas.getContext("2d");
		temporaryCanvas.width = model.canvas.width;
		temporaryCanvas.height = model.canvas.height;
		temporaryContext.drawImage(model.canvas, 0, 0);
		const mainBoundingClientRect = model.canvas.getBoundingClientRect();
		model.renderable.getRenderers().forEach((renderer) => {
			renderer.getViewProps().forEach((viewProp) => {
				if (viewProp.getContainer) {
					const canvasList = viewProp.getContainer().getElementsByTagName("canvas");
					for (let i = 0; i < canvasList.length; i++) {
						const currentCanvas = canvasList[i];
						const boundingClientRect = currentCanvas.getBoundingClientRect();
						const newXPosition = boundingClientRect.x - mainBoundingClientRect.x;
						const newYPosition = boundingClientRect.y - mainBoundingClientRect.y;
						temporaryContext.drawImage(currentCanvas, newXPosition, newYPosition);
					}
				}
			});
		});
		const screenshot = temporaryCanvas.toDataURL(format);
		temporaryCanvas.remove();
		publicAPI.invokeImageReady(screenshot);
	}
	publicAPI.captureNextImage = (format = "image/png", { resetCamera = false, size = null, scale = 1 } = {}) => {
		if (model.deleted) return null;
		model.imageFormat = format;
		const previous = model.notifyStartCaptureImage;
		model.notifyStartCaptureImage = true;
		model._screenshot = { size: !!size || scale !== 1 ? size || model.size.map((val) => val * scale) : null };
		return new Promise((resolve, reject) => {
			const subscription = publicAPI.onImageReady((imageURL) => {
				if (model._screenshot.size === null) {
					model.notifyStartCaptureImage = previous;
					subscription.unsubscribe();
					if (model._screenshot.placeHolder) {
						model.size = model._screenshot.originalSize;
						publicAPI.modified();
						if (model._screenshot.cameras) model._screenshot.cameras.forEach(({ restoreParamsFn, arg }) => restoreParamsFn(arg));
						publicAPI.traverseAllPasses();
						model.el.removeChild(model._screenshot.placeHolder);
						model._screenshot.placeHolder.remove();
						model._screenshot = null;
					}
					resolve(imageURL);
				} else {
					const tmpImg = document.createElement("img");
					tmpImg.style = SCREENSHOT_PLACEHOLDER;
					tmpImg.src = imageURL;
					model._screenshot.placeHolder = model.el.appendChild(tmpImg);
					model.canvas.style.display = "none";
					model._screenshot.originalSize = model.size;
					model.size = model._screenshot.size;
					model.rootOpenGLRenderWindow?.resizeFromChildRenderWindows();
					model._screenshot.size = null;
					publicAPI.modified();
					if (resetCamera) {
						const isUserResetCamera = resetCamera !== true;
						model._screenshot.cameras = model.renderable.getRenderers().map((renderer) => {
							const camera = renderer.getActiveCamera();
							const params = camera.get("focalPoint", "position", "parallelScale");
							return {
								resetCameraArgs: isUserResetCamera ? { renderer } : void 0,
								resetCameraFn: isUserResetCamera ? resetCamera : renderer.resetCamera,
								restoreParamsFn: camera.set,
								arg: JSON.parse(JSON.stringify(params))
							};
						});
						model._screenshot.cameras.forEach(({ resetCameraFn, resetCameraArgs }) => resetCameraFn(resetCameraArgs));
					}
					publicAPI.traverseAllPasses();
				}
			});
		});
	};
	let hardwareMaximumLineWidth;
	publicAPI.getHardwareMaximumLineWidth = () => {
		if (hardwareMaximumLineWidth != null) return hardwareMaximumLineWidth;
		const gl = publicAPI.get3DContext();
		const lineWidthRange = gl.getParameter(gl.ALIASED_LINE_WIDTH_RANGE);
		hardwareMaximumLineWidth = lineWidthRange[1];
		return lineWidthRange[1];
	};
