	publicAPI.getCoincidentParameters = () => {
		let cp = {
			factor: 0,
			offset: 0
		};
		const prop = (model.WebGPUActor?.getRenderable())?.getProperty?.();
		if (!prop) return cp;
		if (model.renderable.getResolveCoincidentTopology() == Resolve.PolygonOffset || prop.getEdgeVisibility() && prop.getRepresentation() === Representation.SURFACE) {
			const primType = model.primitiveType;
			if (primType === PrimitiveTypes.Verts || prop.getRepresentation() === Representation.POINTS) cp = model.renderable.getCoincidentTopologyPointOffsetParameter();
			else if (primType === PrimitiveTypes.Lines || prop.getRepresentation() === Representation.WIREFRAME) cp = model.renderable.getCoincidentTopologyLineOffsetParameters();
			else if (primType === PrimitiveTypes.Triangles || primType === PrimitiveTypes.TriangleStrips) cp = model.renderable.getCoincidentTopologyPolygonOffsetParameters();
			if (primType === PrimitiveTypes.TriangleEdges || primType === PrimitiveTypes.TriangleStripEdges) {
				cp = model.renderable.getCoincidentTopologyPolygonOffsetParameters();
				cp.factor /= 2;
				cp.offset /= 2;
			}
		}
		const selector = model.WebGPURenderer?.getSelector?.();
		if (selector && selector.getFieldAssociation() === FieldAssociations.FIELD_ASSOCIATION_POINTS) cp.offset -= 2;
		return cp;
	};
